SELECT 'HALEMAUMAU', 'Halemaʻumaʻu', 'KRATER', 19.4072, -155.2834, KIL_API.punkt(-155.2834, 19.4072), 822.1, 200, 28, 2600,
       'Krater in der Gipfelcaldera, seit 12/2024 mit Fontänen-Episoden',
       'Krater in der Gipfelcaldera, seit 12/2024 mit Fontänen-Episoden. Das „Haus des ewigen Feuers“. Ein Lavasee füllte es von 1823 bis 1924 und von 2008 bis 2018; seit Dezember 2024 werfen Fontänen-Episoden Lava auf den Kraterboden [L].', 'L', 'M' FROM DUAL
 WHERE NOT EXISTS (SELECT 1 FROM KIL_ORT WHERE SCHLUESSEL = 'HALEMAUMAU')
/

