-- ---------------------------------------------------------------- Drehbücher und Kapitel

INSERT INTO KIL_DREHBUCH (SCHLUESSEL, TITEL, ZEITRAUM, DATUM_VON, DATUM_BIS, ORT_ID, KURZTEXT, KAPITEL)
SELECT '1959', 'Kīlauea Iki 1959', '1959', DATE '1959-08-14', DATE '1959-12-17', (SELECT ORT_ID FROM KIL_ORT WHERE SCHLUESSEL = 'KILAUEA_IKI'),
       '36 Tage, 17 Fontänen-Episoden, die höchste mit 580 m. Die Lava füllt den Krater zu einem See, der Jahrzehnte zum Erstarren braucht.', 6 FROM DUAL
 WHERE NOT EXISTS (SELECT 1 FROM KIL_DREHBUCH WHERE SCHLUESSEL = '1959')
/

INSERT INTO KIL_KAPITEL (DREHBUCH_ID, NR, DATUM_TEXT, DATUM_VON, DATUM_BIS, TITEL, TEXT, SIM_STUNDEN, TEMPO, TEMPO_FAKTOR)
SELECT D.DREHBUCH_ID, 1, 'August bis November 1959', DATE '1959-08-14', DATE '1959-11-14', 'Magma steigt auf',
       'Seit August zeichnen die Seismographen Beben in 45 bis 60 km Tiefe auf, dann immer flacher. Der Gipfel hebt sich. Im Schnitt sieht man, wie sich die Speicher füllen [L USGS; Ablauf im Modell A].',
       288, '1 Tag je Sekunde', 86400 FROM KIL_DREHBUCH D
 WHERE D.SCHLUESSEL = '1959' AND NOT EXISTS (SELECT 1 FROM KIL_KAPITEL K WHERE K.DREHBUCH_ID = D.DREHBUCH_ID AND K.NR = 1)
/

INSERT INTO KIL_KAPITEL (DREHBUCH_ID, NR, DATUM_TEXT, DATUM_VON, DATUM_BIS, TITEL, TEXT, SIM_STUNDEN, TEMPO, TEMPO_FAKTOR)
SELECT D.DREHBUCH_ID, 2, '14. November 1959, 20:08', NULL, NULL, 'Ein Vorhang aus Feuer',
       'An der Südwand des Kīlauea Iki reißt eine Spalte auf; anderthalb Stunden später ist sie rund 900 m lang. Lava schießt in einer Reihe von Fontänen hoch und stürzt in den Krater [L].',
       0.83, '2 Minuten je Sekunde', 120 FROM KIL_DREHBUCH D
 WHERE D.SCHLUESSEL = '1959' AND NOT EXISTS (SELECT 1 FROM KIL_KAPITEL K WHERE K.DREHBUCH_ID = D.DREHBUCH_ID AND K.NR = 2)
/

INSERT INTO KIL_KAPITEL (DREHBUCH_ID, NR, DATUM_TEXT, DATUM_VON, DATUM_BIS, TITEL, TEXT, SIM_STUNDEN, TEMPO, TEMPO_FAKTOR)
SELECT D.DREHBUCH_ID, 3, '15. bis 19. November 1959', NULL, NULL, 'Ein Schlot setzt sich durch',
       'Die Spalte verstummt bis auf einen Schlot im Westen. Seine Fontäne wächst bis auf 380 m. Bims und Schlacke fallen im Südwesten und bauen den Puʻu Puaʻi auf; der Krater füllt sich zu einem See aus Lava [L].',
       2, '4 Minuten je Sekunde', 240 FROM KIL_DREHBUCH D
 WHERE D.SCHLUESSEL = '1959' AND NOT EXISTS (SELECT 1 FROM KIL_KAPITEL K WHERE K.DREHBUCH_ID = D.DREHBUCH_ID AND K.NR = 3)
/

INSERT INTO KIL_KAPITEL (DREHBUCH_ID, NR, DATUM_TEXT, DATUM_VON, DATUM_BIS, TITEL, TEXT, SIM_STUNDEN, TEMPO, TEMPO_FAKTOR)
SELECT D.DREHBUCH_ID, 4, '21. November 1959', NULL, NULL, 'Rückfluss',
       'Episode 1 endet, der See ist 98 m tief. Kaum ist die Fontäne still, fließt Lava aus dem See in den Schlot zurück, später mit einem Strudel gegen den Uhrzeigersinn. Das wiederholt sich nach den meisten der 17 Episoden [L; hier als Sog am Schlot, A].',
       0.67, '2 Minuten je Sekunde', 120 FROM KIL_DREHBUCH D
 WHERE D.SCHLUESSEL = '1959' AND NOT EXISTS (SELECT 1 FROM KIL_KAPITEL K WHERE K.DREHBUCH_ID = D.DREHBUCH_ID AND K.NR = 4)
/

INSERT INTO KIL_KAPITEL (DREHBUCH_ID, NR, DATUM_TEXT, DATUM_VON, DATUM_BIS, TITEL, TEXT, SIM_STUNDEN, TEMPO, TEMPO_FAKTOR)
SELECT D.DREHBUCH_ID, 5, '17. Dezember 1959', DATE '1959-12-17', DATE '1959-12-17', 'Die höchste Fontäne',
       'Episode 15: Die Fontäne steigt auf rund 580 m, die höchste in Hawaiʻi im 20. Jahrhundert [L, USGS: 1 900 Fuß]. Der See steigt wieder; der Wind trägt Peles Haar nach Südwesten.',
       0.75, '2 Minuten je Sekunde', 120 FROM KIL_DREHBUCH D
 WHERE D.SCHLUESSEL = '1959' AND NOT EXISTS (SELECT 1 FROM KIL_KAPITEL K WHERE K.DREHBUCH_ID = D.DREHBUCH_ID AND K.NR = 5)
/

INSERT INTO KIL_KAPITEL (DREHBUCH_ID, NR, DATUM_TEXT, DATUM_VON, DATUM_BIS, TITEL, TEXT, SIM_STUNDEN, TEMPO, TEMPO_FAKTOR)
SELECT D.DREHBUCH_ID, 6, '20. Dezember 1959', NULL, NULL, 'Der See erstarrt',
       'Nach 36 Tagen ist es vorbei. Der See war bis zu 126 m tief; seine Kruste trägt bald, aber innen bleibt er Jahrzehnte heiß. Heute führt der Kīlauea Iki Trail über ihn [L]. Hier kühlt seine Oberfläche in zwei Stunden.',
       2, '10 Minuten je Sekunde', 600 FROM KIL_DREHBUCH D
 WHERE D.SCHLUESSEL = '1959' AND NOT EXISTS (SELECT 1 FROM KIL_KAPITEL K WHERE K.DREHBUCH_ID = D.DREHBUCH_ID AND K.NR = 6)
/

INSERT INTO KIL_DREHBUCH (SCHLUESSEL, TITEL, ZEITRAUM, DATUM_VON, DATUM_BIS, ORT_ID, KURZTEXT, KAPITEL)
SELECT 'maunaulu', 'Mauna Ulu 1969–1974', '1969–1974', DATE '1969-06-01', DATE '1974-07-22', (SELECT ORT_ID FROM KIL_ORT WHERE SCHLUESSEL = 'MAUNA_ULU'),
       'Eine Spaltenreihe, zwölf Fontänen-Episoden bis 540 m, dann fünf Jahre Lavasee und Ströme bis ins Meer. Es wächst ein Schild von 121 m.', 5 FROM DUAL
 WHERE NOT EXISTS (SELECT 1 FROM KIL_DREHBUCH WHERE SCHLUESSEL = 'maunaulu')
/

INSERT INTO KIL_KAPITEL (DREHBUCH_ID, NR, DATUM_TEXT, DATUM_VON, DATUM_BIS, TITEL, TEXT, SIM_STUNDEN, TEMPO, TEMPO_FAKTOR)
SELECT D.DREHBUCH_ID, 1, '24. Mai 1969', NULL, NULL, 'Spalten zwischen ʻAloʻi und ʻAlae',
       'Zwischen zwei Grubenkratern der Ostriftzone öffnet sich eine Reihe von Spalten. Ein Vorhang aus niedrigen Fontänen, die Lava fließt nach Süden [L].',
       0.83, '2 Minuten je Sekunde', 120 FROM KIL_DREHBUCH D
 WHERE D.SCHLUESSEL = 'maunaulu' AND NOT EXISTS (SELECT 1 FROM KIL_KAPITEL K WHERE K.DREHBUCH_ID = D.DREHBUCH_ID AND K.NR = 1)
/

INSERT INTO KIL_KAPITEL (DREHBUCH_ID, NR, DATUM_TEXT, DATUM_VON, DATUM_BIS, TITEL, TEXT, SIM_STUNDEN, TEMPO, TEMPO_FAKTOR)
SELECT D.DREHBUCH_ID, 2, 'Juni bis Dezember 1969', DATE '1969-06-01', DATE '1969-12-30', 'Zwölf Fontänen-Episoden',
       'Die Spalten erlöschen bis auf einen Schlot. Er wirft in Episoden Fontänen von 200 bis 540 m aus, dazwischen Stunden der Ruhe [L].',
       1.83, '2 Minuten je Sekunde', 120 FROM KIL_DREHBUCH D
 WHERE D.SCHLUESSEL = 'maunaulu' AND NOT EXISTS (SELECT 1 FROM KIL_KAPITEL K WHERE K.DREHBUCH_ID = D.DREHBUCH_ID AND K.NR = 2)
/

INSERT INTO KIL_KAPITEL (DREHBUCH_ID, NR, DATUM_TEXT, DATUM_VON, DATUM_BIS, TITEL, TEXT, SIM_STUNDEN, TEMPO, TEMPO_FAKTOR)
SELECT D.DREHBUCH_ID, 3, '1970 bis 1971', NULL, NULL, 'See und Ströme',
       'Im wachsenden Kegel steht ein Lavasee; aus ihm laufen Ströme über die Flanke nach Süden zur Hōlei Pali [L]. Hier: 10 m³/s über vier Stunden.',
       4, '10 Minuten je Sekunde', 600 FROM KIL_DREHBUCH D
 WHERE D.SCHLUESSEL = 'maunaulu' AND NOT EXISTS (SELECT 1 FROM KIL_KAPITEL K WHERE K.DREHBUCH_ID = D.DREHBUCH_ID AND K.NR = 3)
/

INSERT INTO KIL_KAPITEL (DREHBUCH_ID, NR, DATUM_TEXT, DATUM_VON, DATUM_BIS, TITEL, TEXT, SIM_STUNDEN, TEMPO, TEMPO_FAKTOR)
SELECT D.DREHBUCH_ID, 4, '1972 bis 1974', DATE '1972-02-01', DATE '1974-07-22', 'Röhren bis zum Meer',
       'Der Strom deckt sich zu: unter einer Kruste fließt die Lava in Röhren weiter, Oberlichter bleiben offen. Die echten Ströme liefen so über Monate 12 km bis ins Meer; hier ist nur ihr Anfang zu sehen [L; Zeitraffer G].',
       3, '10 Minuten je Sekunde', 600 FROM KIL_DREHBUCH D
 WHERE D.SCHLUESSEL = 'maunaulu' AND NOT EXISTS (SELECT 1 FROM KIL_KAPITEL K WHERE K.DREHBUCH_ID = D.DREHBUCH_ID AND K.NR = 4)
/

INSERT INTO KIL_KAPITEL (DREHBUCH_ID, NR, DATUM_TEXT, DATUM_VON, DATUM_BIS, TITEL, TEXT, SIM_STUNDEN, TEMPO, TEMPO_FAKTOR)
SELECT D.DREHBUCH_ID, 5, '22. Juli 1974', NULL, NULL, 'Ende',
       'Der Ausbruch endet nach fünf Jahren. Mauna Ulu steht 121 m über dem alten Gelände, seine Ströme bedecken rund 46 km² [L].',
       1, '10 Minuten je Sekunde', 600 FROM KIL_DREHBUCH D
 WHERE D.SCHLUESSEL = 'maunaulu' AND NOT EXISTS (SELECT 1 FROM KIL_KAPITEL K WHERE K.DREHBUCH_ID = D.DREHBUCH_ID AND K.NR = 5)
/

INSERT INTO KIL_DREHBUCH (SCHLUESSEL, TITEL, ZEITRAUM, DATUM_VON, DATUM_BIS, ORT_ID, KURZTEXT, KAPITEL)
SELECT 'puuoo', 'Puʻu ʻŌʻō und Kamokuna 1983–2018', '1983–2017', DATE '1983-06-01', DATE '2017-03-20', (SELECT ORT_ID FROM KIL_ORT WHERE SCHLUESSEL = 'PUU_OO'),
       '35 Jahre an einem Kegel: erst hohe Fontänen, dann Röhren bis zur Küste. 2016 läuft die Lava bei Kamokuna ins Meer, das Delta bricht ab, ein Feuerwehrschlauch fällt aus der Klippe.', 7 FROM DUAL
 WHERE NOT EXISTS (SELECT 1 FROM KIL_DREHBUCH WHERE SCHLUESSEL = 'puuoo')
/

INSERT INTO KIL_KAPITEL (DREHBUCH_ID, NR, DATUM_TEXT, DATUM_VON, DATUM_BIS, TITEL, TEXT, SIM_STUNDEN, TEMPO, TEMPO_FAKTOR)
SELECT D.DREHBUCH_ID, 1, '3. Januar 1983', NULL, NULL, 'Spalten in der Ostriftzone',
       'Nach einem Gang aus dem Gipfel öffnen sich Spalten über rund 8 km der Ostriftzone. Bald sammelt sich alles an einer Stelle [L].',
       0.67, '2 Minuten je Sekunde', 120 FROM KIL_DREHBUCH D
 WHERE D.SCHLUESSEL = 'puuoo' AND NOT EXISTS (SELECT 1 FROM KIL_KAPITEL K WHERE K.DREHBUCH_ID = D.DREHBUCH_ID AND K.NR = 1)
